/* Effect descriptors are generated from resolved Gen 3 Showdown data. */
/* Native handler IDs are the reviewed executable-semantics boundary. */
typedef enum {
    GEN3_EFFECT_MOVE = 0,
    GEN3_EFFECT_SIDE_CONDITION = 1,
    GEN3_EFFECT_ABILITY = 2,
    GEN3_EFFECT_ITEM = 3,
    GEN3_EFFECT_STATUS = 4,
} Gen3EffectKind;

typedef enum {
    GEN3_EFFECT_EVENT_BASE_POWER = 0,
    GEN3_EFFECT_EVENT_ENTRY_HAZARD = 1,
    GEN3_EFFECT_EVENT_RESIDUAL = 2,
    GEN3_EFFECT_EVENT_SIDE_RESTART = 3,
    GEN3_EFFECT_EVENT_SIDE_START = 4,
    GEN3_EFFECT_EVENT_SWITCH_OUT = 5,
    GEN3_EFFECT_EVENT_TRY_HIT = 6,
    GEN3_EFFECT_EVENT_COUNT = 7,
} Gen3EffectEventId;

typedef enum {
    GEN3_NATIVE_HANDLER_NONE = 0,
    GEN3_NATIVE_HANDLER_SPIKES_START = 1,
    GEN3_NATIVE_HANDLER_SPIKES_RESTART = 2,
    GEN3_NATIVE_HANDLER_SPIKES_ENTRY = 3,
    GEN3_NATIVE_HANDLER_LEFTOVERS_RESIDUAL = 4,
    GEN3_NATIVE_HANDLER_NATURAL_CURE_SWITCH_OUT = 5,
    GEN3_NATIVE_HANDLER_STURDY_TRY_HIT = 6,
    GEN3_NATIVE_HANDLER_TORRENT_BASE_POWER = 7,
    GEN3_NATIVE_HANDLER_COUNT = 8,
} Gen3NativeHandlerId;

#define GEN3_EFFECT_CAP_AIRBORNE (UINT32_C(1) << 0)
#define GEN3_EFFECT_CAP_GROUND_IMMUNE (UINT32_C(1) << 1)
enum { GEN3_HANDLER_ORDER_DEFAULT = 32767 };
enum { GEN3_CONDITION_SPIKES = 1 };

typedef struct {
    uint16_t effect_id;
    uint8_t kind;
    uint8_t handler_count;
    uint16_t first_handler;
    uint32_t capability_bits;
    const char *name;
} Gen3EffectDescriptor;

typedef struct {
    uint16_t event_id;
    uint16_t native_handler_id;
    int16_t order;
    int16_t priority;
    int16_t sub_order;
} Gen3HandlerDescriptor;

